import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids derived only from seed.

    The same (n, seed) pair always yields the same list, in the same order,
    on every run. The function uses a private seeded generator and does not
    touch global random state, the clock, the environment, or any I/O.
    Raises ValueError when n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**31), n)


def test_make_ids_length() -> None:
    assert len(make_ids(5, 1)) == 5


def test_make_ids_zero() -> None:
    assert make_ids(0, 1) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(50, 7)
    assert len(set(ids)) == len(ids)


def test_make_ids_deterministic() -> None:
    assert make_ids(20, 42) == make_ids(20, 42)


def test_make_ids_seed_changes_output() -> None:
    assert make_ids(10, 1) != make_ids(10, 2)


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
